C15 = (A15(1)*Z + A15(2)) / ((B15(1)*Z + B15(2))*Z + 1.D0)
C16 = (A16(1)*Z + A16(2)) / (B16(1)*Z + 1.D0)
!
T = (A18(1)*U + A17(1))*U + C16
T = (((((((((((((((T*U + C15)*U + C14)*U + C13)*U + C12)*U + &
&C11)*U + C10)*U + C9)*U + C8)*U + C7)*U + C6)*U + &
&C5)*U + C4)*U + C3)*U + C2)*U + C1)*U + C0
!
IF (L .LT. 1.D0) GO TO 10
   QANS = E*(W + RT2PIN*T/RTA)
   ANS = 0.5D0 + (0.5D0 - QANS)
   RETURN
10 ANS = E*(W - RT2PIN*T/RTA)
QANS = 0.5D0 + (0.5D0 - ANS)
RETURN
END SUBROUTINE DGR29

SUBROUTINE DGR17 (A, Y, L, Z, RTA, ANS, QANS)
IMPLICIT NONE
INTENT(IN) A, L, RTA, Y
INTENT(INOUT) ANS, QANS, Z
!-----------------------------------------------------------------------
!
!            ALGORITHM USING MINIMAX APPROXIMATIONS
!                        FOR C0,...,C10
!
!-----------------------------------------------------------------------
DOUBLE PRECISION A, Y, L, Z, RTA, ANS, QANS
DOUBLE PRECISION E, RT2PIN, T, U, W
DOUBLE PRECISION C0, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10
DOUBLE PRECISION A0(5), A1(4), A2(4), A3(4), A4(3), A5(2), &
&A6(2), A7(2), A8(2), A9(3), A10(2)
DOUBLE PRECISION B0(6), B1(6), B2(5), B3(4), B4(4), B5(4), &
&B6(3), B7(3), B8(2)
DOUBLE PRECISION DERFC1
!------------------------
!     RT2PIN = 1/DSQRT(2*PI)
!------------------------
DATA RT2PIN /.398942280401432678D0/
!------------------------
data A0(1) /-.73324404807556026D-03/, A0(2) /-.11758531313175796D-01/, &
&A0(3) /-.76816029947195974D-01/, A0(4) /-.24232172943558393D+00/, &
&A0(5) /-.33333333333333333D+00/
data B0(1)  /.10555647473018528D-06/, B0(2)  /.73121701584237188D-03/, &
&B0(3)  /.13250270182342259D-01/, B0(4)  /.10288837674434487D+00/, &
&B0(5)  /.43024494247383254D+00/, B0(6)  /.97696518830675185D+00/
!------------------------
data A1(1) /-.16746784557475121D-03/, A1(2) /-.16090334014223031D-02/, &
&A1(3) /-.52949366601406939D-02/, A1(4) /-.18518518518518417D-02/
data B1(1)  /.12328086517283227D-05/, B1(2)  /.98671953445602142D-03/, &
&B1(3)  /.15954049115266936D-01/, B1(4)  /.11439610256504704D+00/, &
&B1(5)  /.45195109694529839D+00/, B1(6)  /.98426579647613593D+00/
!------------------------
data A2(1)  /.12049855113125238D-04/, A2(2)  /.13743853858711134D-03/, &
&A2(3)  /.15067356806896441D-02/, A2(4)  /.41335978835983393D-02/
data B2(1)  /.15927093345670077D-02/, B2(2)  /.22316881460606523D-01/, &
&B2(3)  /.14009848931638062D+00/, B2(4)  /.50379606871703058D+00/, &
&B2(5)  /.10131761625405203D+01/
!------------------------
data A3(1)  /.46318872971699924D-05/, A3(2)  /.13012396979747783D-04/, &
&A3(3)  /.81804333975935872D-03/, A3(4)  /.64943415637082551D-03/
data B3(1)  /.12414068921653593D-01/, B3(2)  /.10044290377295469D+00/, &
&B3(3)  /.42226789458984594D+00/, B3(4)  /.90628317147366376D+00/
!------------------------
data A4(1) /-.37567394580525597D-05/, A4(2) /-.82794205648271314D-04/, &
&A4(3) /-.86188829773520181D-03/
data B4(1)  /.31290397554562032D-01/, B4(2)  /.16988291247058802D+00/, &
&B4(3)  /.57225859400072754D+00/, B4(4)  /.10057375981227881D+01/
!------------------------
data A5(1) /-.43263341886764011D-03/, A5(2) /-.33679854644784478D-03/
data B5(1)  /.22714615451529335D-01/, B5(2)  /.17081504060220639D+00/, &
&B5(3)  /.60019022026983067D+00/, B5(4)  /.10775200414676195D+01/
!------------------------
data A6(1) /-.12962670089753501D-03/, A6(2)  /.53130115408837152D-03/
data B6(1)  /.65929776650152292D-01/, B6(2)  /.45957439582639129D+00/, &
&B6(3)  /.87058903334443855D+00/
!------------------------
data A7(1)  /.47861364421780889D-03/, A7(2)  /.34438428473168988D-03/
data B7(1)  /.27176241899664174D+00/, B7(2)  /.78991370162247144D+00/, &
&B7(3)  /.12396875725833093D+01/
!------------------------
data A8(1)  /.27086391808339115D-03/, A8(2) /-.65256615574219131D-03/
data B8(1)  /.44207055629598579D+00/, B8(2)  /.87002402612484571D+00/
!------------------------
data A9(1) / .84725086921921823D-03/, A9(2) /-.14838721516118744D-03/, &
&A9(3) /-.60335050249571475D-03/
!------------------------
data A10(1)/-.19144384985654775D-02/, A10(2) /.13324454494800656D-02/
!------------------------
E = DEXP(-Y)
W = 0.5D0*DERFC1(1,DSQRT(Y))
U = 1.D0/A
Z = DSQRT(Z + Z)
IF (L .LT. 1.D0) Z = -Z
!
C0 = ((((A0(1)*Z + A0(2))*Z + A0(3))*Z + A0(4))*Z + A0(5)) / &
&((((((B0(1)*Z + B0(2))*Z + B0(3))*Z + B0(4))*Z + B0(5))*Z + &
&B0(6))*Z + 1.D0)
C1 = (((A1(1)*Z + A1(2))*Z + A1(3))*Z + A1(4)) / ((((((B1(1)*Z + &
&B1(2))*Z + B1(3))*Z + B1(4))*Z + B1(5))*Z + B1(6))*Z + &
&1.D0)
C2 = (((A2(1)*Z + A2(2))*Z + A2(3))*Z + A2(4)) / (((((B2(1)*Z + &
&B2(2))*Z + B2(3))*Z + B2(4))*Z + B2(5))*Z + 1.D0)
C3 = (((A3(1)*Z + A3(2))*Z + A3(3))*Z + A3(4)) / ((((B3(1)*Z + &
&B3(2))*Z + B3(3))*Z + B3(4))*Z + 1.D0)
C4 = ((A4(1)*Z + A4(2))*Z + A4(3)) / ((((B4(1)*Z + B4(2))*Z + &
&B4(3))*Z + B4(4))*Z + 1.D0)
C5 = (A5(1)*Z + A5(2)) / ((((B5(1)*Z + B5(2))*Z + B5(3))*Z + &
&B5(4))*Z + 1.D0)
C6 = (A6(1)*Z + A6(2))/(((B6(1)*Z + B6(2))*Z + B6(3))*Z + 1.D0)
C7 = (A7(1)*Z + A7(2))/(((B7(1)*Z + B7(2))*Z + B7(3))*Z + 1.D0)
C8 = (A8(1)*Z + A8(2))/((B8(1)*Z + B8(2))*Z + 1.D0)
C9 = (A9(1)*Z + A9(2))*Z + A9(3)
C10 = A10(1)*Z + A10(2)
!
T = (((((((((C10*U + C9)*U + C8)*U + C7)*U + C6)*U + C5)*U + &
&C4)*U + C3)*U + C2)*U + C1)*U + C0
!
IF (L .LT. 1.D0) GO TO 10
   QANS = E*(W + RT2PIN*T/RTA)
   ANS = 0.5D0 + (0.5D0 - QANS)
   RETURN
10 ANS = E*(W - RT2PIN*T/RTA)
QANS = 0.5D0 + (0.5D0 - ANS)
RETURN
END SUBROUTINE DGR17

SUBROUTINE DGINV (A, X, P, Q, IERR)
IMPLICIT NONE
INTENT(IN) A, P, Q
INTENT(OUT) X
INTENT(INOUT) IERR
INTEGER IERR
INTEGER IER, IND
!-----------------------------------------------------------------------
!
!                        DOUBLE PRECISION
!             INVERSE INCOMPLETE GAMMA RATIO FUNCTION
!
!     GIVEN POSITIVE A, AND NONEGATIVE P AND Q WHERE P + Q = 1.
!     THEN X IS COMPUTED WHERE P(A,X) = P AND Q(A,X) = Q. SCHRODER
!     ITERATION IS EMPLOYED.
!
!                        ------------
!
!     X IS A VARIABLE. IF P = 0 THEN X IS ASSIGNED THE VALUE 0,
!     AND IF Q = 0 THEN X IS SET TO THE LARGEST FLOATING POINT
!     NUMBER AVAILABLE. OTHERWISE, DGINV ATTEMPTS TO OBTAIN
!     A SOLUTION FOR P(A,X) = P AND Q(A,X) = Q. IF THE ROUTINE
!     IS SUCCESSFUL THEN THE SOLUTION IS STORED IN X.
!
!     IERR IS A VARIABLE THAT REPORTS THE STATUS OF THE RESULTS.
!     WHEN THE ROUTINE TERMINATES, IERR HAS ONE OF THE FOLLOWING
!     VALUES ...
!
!       IERR =  0    THE SOLUTION WAS OBTAINED. ITERATION WAS
!                    NOT USED.
!       IERR.GT.0    THE SOLUTION WAS OBTAINED. IERR ITERATIONS
!                    WERE PERFORMED.
!       IERR = -2    (INPUT ERROR) A .LE. 0
!       IERR = -3    NO SOLUTION WAS OBTAINED. THE RATIO Q/A
!                    IS TOO LARGE.
!       IERR = -4    (INPUT ERROR) P OR Q IS NEGATIVE, OR
!                    P + Q .NE. 1.
!       IERR = -6    10 ITERATIONS WERE PERFORMED. THE MOST
!                    RECENT VALUE OBTAINED FOR X IS GIVEN.
!                    (THIS SETTING SHOULD NEVER OCCUR.)
!       IERR = -7    ITERATION FAILED. NO VALUE IS GIVEN FOR X.
!                    THIS MAY OCCUR WHEN X IS APPROXIMATELY 0.
!       IERR = -8    A VALUE FOR X HAS BEEN OBTAINED, BUT THE
!                    ROUTINE IS NOT CERTAIN OF ITS ACCURACY.
!                    ITERATION CANNOT BE PERFORMED IN THIS
!                    CASE. THIS SETTING CAN OCCUR ONLY WHEN
!                    P OR Q IS APPROXIMATELY 0.
!
!-----------------------------------------------------------------------
!     WRITTEN BY ALFRED H. MORRIS, JR.
!        NAVAL SURFACE WARFARE CENTER
!        DAHLGREN, VIRGINIA
!     WRITTEN ... JANUARY 1992
!------------------------
DOUBLE PRECISION A, X, P, Q
REAL P0, Q0, X0
DOUBLE PRECISION AM1, APN, AP1, AP2, AP3, B, C, C1, C2, C3, C4, &
&C5, D, E, EPS, G, H, LN10, PN, QG, QN, R, RTA, &
&S, SUM, S2, T, TOL, U, W, XMIN, XN, Y, Z, AMIN
DOUBLE PRECISION DPMPAR, DLNREL, DGAMMA, DGAMLN, DGMLN1, DRCOMP
!------------------------
!     LN10 = LN(10)
!     C = EULER CONSTANT
!------------------------
DATA LN10 /2.302585D0/
DATA C  /.577215664901533D0/
!------------------------
DATA TOL /1.D-10/
!------------------------
!
!     ****** E AND XMIN ARE MACHINE DEPENDENT CONSTANTS. E IS THE
!            SMALLEST NUMBER FOR WHICH 1.0 + E .GT. 1.0, AND XMIN
!            IS THE SMALLEST POSITIVE NUMBER.
!
             E = DPMPAR(1)
             XMIN = DPMPAR(2)
!
!------------------------
X = 0.D0
IF (A .LE. 0.D0) GO TO 500
IF (P .LT. 0.D0 .OR. Q .LT. 0.D0) GO TO 520
T = ((P + Q) - 0.5D0) - 0.5D0
IF (DABS(T) .GT. 5.D0*DMAX1(E,1.D-30)) GO TO 520
!
IERR = 0
XMIN = XMIN/E
IF ((P/E) .LE. XMIN) GO TO 400
IF ((Q/E) .LE. XMIN) GO TO 560
IF (A .EQ. 1.D0) GO TO 410
!
E = DMAX1(E,1.D-30)
EPS = 1.D3*E
AMIN = 5.D3
IF (E .LT. 1.D-17) AMIN = 2.D6
IF (A .GE. AMIN) GO TO 50
!
!        GET AN INITIAL APPROXIMATION USING THE SINGLE
!         PRECISION ARITHMETIC (IF THIS IS POSSIBLE)
!
P0 = P
Q0 = Q
IF (P0 .EQ. 0.0 .OR.Q0 .EQ. 0.0) GO TO 10
CALL GAMINV (SNGL(A), X0, 0.0, P0, Q0, IER)
IF (IER .LT. 0.0 .AND. IER .NE. -8) GO TO 10
IERR = MAX0(IER,0)
IF (X0 .GT. 1.E34) GO TO 10
   XN = X0
   GO TO 100
!
10 IF (A .GT. 1.D0) GO TO 50
XN = 0.D0
!
!        SELECTION OF THE INITIAL APPROXIMATION XN OF X
!                       WHEN A .LT. 1
!
G = DGAMMA(A + 1.D0)
QG = Q*G
IF (QG .EQ. 0.D0) GO TO 560
B = QG/A
IF (QG .GT. 0.6D0*A) GO TO 30
IF (A .GE. 0.30D0 .OR. B .LT. 0.35D0) GO TO 20
   T = DEXP(-(B + C))
   U = T*DEXP(T)
   XN = T*DEXP(U)
   GO TO 100
!
20 IF (B .GE. 0.45D0) GO TO 30
IF (B .EQ. 0.D0) GO TO 560
Y = -DLOG(B)
S = 0.5D0 + (0.5D0 - A)
Z = DLOG(Y)
T = Y - S*Z
IF (B .LT. 0.15D0) GO TO 21
   XN = Y - S*DLOG(T) - DLOG(1.D0 + S/(T + 1.D0))
   GO TO 200
21 IF (B .LE. 1.D-2) GO TO 22
   U = ((T + 2.D0*(3.D0 - A))*T + (2.D0 - A)*(3.D0 - A))/ &
&((T + (5.D0 - A))*T + 2.D0)
   XN = Y - S*DLOG(T) - DLOG(U)
   GO TO 200
22 C1 = -S*Z
C2 = -S*(1.D0 + C1)
C3 =  S*((0.5D0*C1 + (2.D0 - A))*C1 + (2.5D0 - 1.5D0*A))
C4 = -S*(((C1/3.D0 + (2.5D0 - 1.5D0*A))*C1 + ((A - 6.D0)*A &
&+ 7.D0))*C1 + ((11.D0*A - 46.D0)*A + 47.D0)/6.D0)
C5 = -S*((((-C1/4.D0 + (11.D0*A - 17.D0)/6.D0)*C1 &
&+ ((-3.D0*A + 13.D0)*A - 13.D0))*C1 &
&+ 0.5D0*(((2.D0*A - 25.D0)*A + 72.D0)*A - 61.D0))*C1 &
&+ (((25.D0*A - 195.D0)*A + 477.D0)*A - 379.D0)/12.D0)
XN = ((((C5/Y + C4)/Y + C3)/Y + C2)/Y + C1) + Y
GO TO 200
!
30 IF (B*Q .GT. 1.D-8) GO TO 31
   XN = DEXP(-(Q/A + C))
   GO TO 40
31 IF (P .LE. 0.9D0) GO TO 32
   XN = DEXP((DLNREL(-Q) + DGMLN1(A))/A)
   GO TO 40
32 XN = DEXP(DLOG(P*G)/A)
!
40 IF (XN .EQ. 0.D0) GO TO 510
T = 0.5D0 + (0.5D0 - XN/(A + 1.D0))
XN = XN/T
GO TO 100
!
!        SELECTION OF THE INITIAL APPROXIMATION XN OF X
!                       WHEN A .GT. 1
!
50 T = P - 0.5D0
IF (Q .LT. 0.5D0) T = 0.5D0 - Q
CALL DPNI (P, Q, T, S, IER)
!
RTA = DSQRT(A)
S2 = S*S
XN = (((12.D0*S2 - 243.D0)*S2 - 923.D0)*S2 + 1472.D0)/204120.D0 &
&- S*(((3753.D0*S2 + 4353.D0)*S2 - 289517.D0)*S2 - 289717.D0) &
&/(146966400.D0*RTA)
XN = (XN/A + S*((9.D0*S2 + 256.D0)*S2 - 433.D0)/(38880.D0*RTA)) &
&- ((3.D0*S2 + 7.D0)*S2 - 16.D0)/810.D0
XN = A + S*RTA + (S2 - 1.D0)/3.D0 + S*(S2 - 7.D0)/(36.D0*RTA) &
&+ XN/A
XN = DMAX1(XN, 0.D0)
!
IF (A .LT. AMIN) GO TO 60
   X = XN
   D = 0.5D0 + (0.5D0 - X/A)
   IF (DABS(D) .GT. 1.D-1) GO TO 60
   IF (DABS(D) .GT. 1.D-3) GO TO 100
   RETURN
!
60 IF (P .LE. 0.5D0) GO TO 70
IF (XN .LT. 3.D0*A) GO TO 200
W = DLOG(Q)
Y = -(W + DGAMLN(A))
D = DMAX1(2.D0, A*(A - 1.D0))
IF (Y .LT. LN10*D) GO TO 61
   S = 1.D0 - A
   Z = DLOG(Y)
   GO TO 22
61 T = A - 1.D0
XN = Y + T*DLOG(XN) - DLNREL(-T/(XN + 1.D0))
XN = Y + T*DLOG(XN) - DLNREL(-T/(XN + 1.D0))
GO TO 200
!
70 AP1 = A + 1.D0
IF (XN .GT. 0.7D0*AP1) GO TO 101
W = DLOG(P) + DGAMLN(AP1)
IF (XN .GT. 0.15D0*AP1) GO TO 80
   AP2 = A + 2.D0
   AP3 = A + 3.D0
   X = DEXP((W + X)/A)
   X = DEXP((W + X - DLOG(1.0 + (X/AP1)*(1.D0 + X/AP2)))/A)
   X = DEXP((W + X - DLOG(1.0 + (X/AP1)*(1.D0 + X/AP2)))/A)
   X = DEXP((W + X - DLOG(1.0 + (X/AP1)*(1.D0 + (X/AP2)*(1.D0 &
&+ X/AP3))))/A)
   XN = X
   IF (XN .LE. 1.D-2*AP1) GO TO 101
!
80 APN = AP1
T = XN/APN
SUM = 1.D0 + T
81 APN = APN + 1.D0
   T = T*(XN/APN)
   SUM = SUM + T
   IF (T .GT. 1.D-4) GO TO 81
T = W - DLOG(SUM)
XN = DEXP((XN + T)/A)
XN = XN*(1.D0 - (A*DLOG(XN) - XN - T)/(A - XN))
GO TO 101
!
!                 SCHRODER ITERATION USING P
!
100 IF (P .GT. 0.5D0) GO TO 200
101 IF (P .LE. XMIN) GO TO 550
AM1 = (A - 0.5D0) - 0.5D0
!
110 IF (IERR .GE. 10) GO TO 530
IERR = IERR + 1
CALL DGRAT (A, XN, PN, QN, IND)
IF (PN .EQ. 0.D0 .OR. QN .EQ. 0.D0) GO TO 550
R = DRCOMP(A,XN)
IF (R .LT. XMIN) GO TO 550
T = (PN - P)/R
W = 0.5D0*(AM1 - XN)
IF (DABS(T) .LE. 0.1D0 .AND. DABS(W*T) .LE. 0.1D0) GO TO 120
   X = XN*(1.D0 - T)
   IF (X .LE. 0.D0) GO TO 540
   D = DABS(T)
   GO TO 121
!
120 H = T*(1.D0 + W*T)
X = XN*(1.D0 - H)
IF (X .LE. 0.D0) GO TO 540
IF (DABS(W) .GE. 1.D0 .AND. DABS(W)*T*T .LE. EPS) RETURN
D = DABS(H)
121 XN = X
IF (D .GT. TOL) GO TO 110
IF (D .LE. EPS) RETURN
IF (DABS(P - PN) .LE. TOL*P) RETURN
GO TO 110
!
!                 SCHRODER ITERATION USING Q
!
200 IF (Q .LE. XMIN) GO TO 550
AM1 = (A - 0.5D0) - 0.5D0
!
210 IF (IERR .GE. 10) GO TO 530
IERR = IERR + 1
CALL DGRAT (A, XN, PN, QN, IND)
IF (PN .EQ. 0.D0 .OR. QN .EQ. 0.D0) GO TO 550
R = DRCOMP(A,XN)
IF (R .LT. XMIN) GO TO 550
T = (Q - QN)/R
W = 0.5D0*(AM1 - XN)
IF (DABS(T) .LE. 0.1D0 .AND. DABS(W*T) .LE. 0.1D0) GO TO 220
   X = XN*(1.D0 - T)
   IF (X .LE. 0.D0) GO TO 540
   D = DABS(T)
   GO TO 221
!
220 H = T*(1.D0 + W*T)
X = XN*(1.D0 - H)
IF (X .LE. 0.D0) GO TO 540
IF (DABS(W) .GE. 1.D0 .AND. DABS(W)*T*T .LE. EPS) RETURN
D = DABS(H)
221 XN = X
IF (D .GT. TOL) GO TO 210
IF (D .LE. EPS) RETURN
IF (DABS(Q - QN) .LE. TOL*Q) RETURN
GO TO 210
!
!                       SPECIAL CASES
!
400 IERR = -8
RETURN
!
410 IF (Q .LT. 0.9D0) GO TO 411
   X = -DLNREL(-P)
   RETURN
411 X = -DLOG(Q)
RETURN
!
!                       ERROR RETURN
!
500 IERR = -2
RETURN
!
510 IERR = -3
RETURN
!
520 IERR = -4
RETURN
!
530 IERR = -6
RETURN
!
540 IERR = -7
RETURN
!
550 X = XN
IERR = -8
RETURN
!
560 X = DPMPAR(3)
IERR = -8
RETURN
END SUBROUTINE DGINV

SUBROUTINE BRATIO (A, B, X, Y, W, W1, IERR)
IMPLICIT NONE
INTENT(IN) A, B, X, Y
INTENT(OUT) W, W1
INTENT(INOUT) IERR
REAL APSER, BASYM, BFRAC, BPSER, BUP, FPSER, SPMPAR
INTEGER IERR
REAL A, B, W, W1, X, Y
INTEGER IERR1, IND, N
REAL A0, B0, EPS, T, X0, Y0, Z
!-----------------------------------------------------------------------
!
!            EVALUATION OF THE INCOMPLETE BETA FUNCTION IX(A,B)
!
!                     --------------------
!
!     IT IS ASSUMED THAT A AND B ARE NONNEGATIVE, AND THAT X .LE. 1
!     AND Y = 1 - X.  BRATIO ASSIGNS W AND W1 THE VALUES
!
!                      W  = IX(A,B)
!                      W1 = 1 - IX(A,B)
!
!     IERR IS A VARIABLE THAT REPORTS THE STATUS OF THE RESULTS.
!     IF NO INPUT ERRORS ARE DETECTED THEN IERR IS SET TO 0 AND
!     W AND W1 ARE COMPUTED. OTHERWISE, IF AN ERROR IS DETECTED,
!     THEN W AND W1 ARE ASSIGNED THE VALUE 0 AND IERR IS SET TO
!     ONE OF THE FOLLOWING VALUES ...
!
!        IERR = 1  IF A OR B IS NEGATIVE
!        IERR = 2  IF A = B = 0
!        IERR = 3  IF X .LT. 0 OR X .GT. 1
!        IERR = 4  IF Y .LT. 0 OR Y .GT. 1
!        IERR = 5  IF X + Y .NE. 1
!        IERR = 6  IF X = A = 0
!        IERR = 7  IF Y = B = 0
!
!--------------------
!     WRITTEN BY ALFRED H. MORRIS, JR.
!        NAVAL SURFACE WARFARE CENTER
!        DAHLGREN, VIRGINIA
!     REVISED ... NOV 1991
!-----------------------------------------------------------------------
REAL LAMBDA
!-----------------------------------------------------------------------
!
!     ****** EPS IS A MACHINE DEPENDENT CONSTANT. EPS IS THE SMALLEST
!            FLOATING POINT NUMBER FOR WHICH 1.0 + EPS .GT. 1.0
!
                 EPS = SPMPAR(1)
!
!-----------------------------------------------------------------------
W = 0.0
W1 = 0.0
IF (A .LT. 0.0 .OR. B .LT. 0.0) GO TO 300
IF (A .EQ. 0.0 .AND. B .EQ. 0.0) GO TO 310
IF (X .LT. 0.0 .OR. X .GT. 1.0) GO TO 320
IF (Y .LT. 0.0 .OR. Y .GT. 1.0) GO TO 330
Z = ((X + Y) - 0.5) - 0.5
IF (ABS(Z) .GT. 3.0*EPS) GO TO 340
!
IERR = 0
IF (X .EQ. 0.0) GO TO 200
IF (Y .EQ. 0.0) GO TO 210
IF (A .EQ. 0.0) GO TO 211
IF (B .EQ. 0.0) GO TO 201
!
EPS = AMAX1(EPS, 1.E-15)
IF (AMAX1(A,B) .LT. 1.E-3*EPS) GO TO 230
!
IND = 0
A0 = A
B0 = B
X0 = X
Y0 = Y
IF (AMIN1(A0, B0) .GT. 1.0) GO TO 30
!
!             PROCEDURE FOR A0 .LE. 1 OR B0 .LE. 1
!
IF (X .LE. 0.5) GO TO 10
IND = 1
A0 = B
B0 = A
X0 = Y
Y0 = X
!
10 IF (B0 .LT. AMIN1(EPS,EPS*A0)) GO TO 80
IF (A0 .LT. AMIN1(EPS,EPS*B0) .AND. B0*X0 .LE. 1.0) GO TO 90
IF (AMAX1(A0, B0) .GT. 1.0) GO TO 20
IF (A0 .GE. AMIN1(0.2, B0)) GO TO 100
IF (X0**A0 .LE. 0.9) GO TO 100
IF (X0 .GE. 0.3) GO TO 110
N = 20
GO TO 130
!
20 IF (B0 .LE. 1.0) GO TO 100
IF (X0 .GE. 0.3) GO TO 110
IF (X0 .GE. 0.1) GO TO 21
IF ((X0*B0)**A0 .LE. 0.7) GO TO 100
21 IF (B0 .GT. 15.0) GO TO 131
N = 20
GO TO 130
!
!             PROCEDURE FOR A0 .GT. 1 AND B0 .GT. 1
!
30 IF (A .GT. B) GO TO 31
   LAMBDA = A - (A + B)*X
   GO TO 32
31 LAMBDA = (A + B)*Y - B
32 IF (LAMBDA .GE. 0.0) GO TO 40
IND = 1
A0 = B
B0 = A
X0 = Y
Y0 = X
LAMBDA = ABS(LAMBDA)
!
40 IF (B0 .LT. 40.0 .AND. B0*X0 .LE. 0.7) GO TO 100
IF (B0 .LT. 40.0) GO TO 140
IF (A0 .GT. B0) GO TO 50
   IF (A0 .LE. 100.0) GO TO 120
   IF (LAMBDA .GT. 0.03*A0) GO TO 120
   GO TO 180
50 IF (B0 .LE. 100.0) GO TO 120
IF (LAMBDA .GT. 0.03*B0) GO TO 120
GO TO 180
!
!            EVALUATION OF THE APPROPRIATE ALGORITHM
!
80 W = FPSER(A0, B0, X0, EPS)
W1 = 0.5 + (0.5 - W)
GO TO 220
!
90 W1 = APSER(A0, B0, X0, EPS)
W = 0.5 + (0.5 - W1)
GO TO 220
!
100 W = BPSER(A0, B0, X0, EPS)
W1 = 0.5 + (0.5 - W)
GO TO 220
!
110 W1 = BPSER(B0, A0, Y0, EPS)
W = 0.5 + (0.5 - W1)
GO TO 220
!
120 W = BFRAC(A0, B0, X0, Y0, LAMBDA, 15.0*EPS)
W1 = 0.5 + (0.5 - W)
GO TO 220
!
130 W1 = BUP(B0, A0, Y0, X0, N, EPS)
B0 = B0 + N
131 CALL BGRAT(B0, A0, Y0, X0, W1, 15.0*EPS, IERR1)
W = 0.5 + (0.5 - W1)
GO TO 220
!
140 N = B0
B0 = B0 - N
IF (B0 .NE. 0.0) GO TO 141
   N = N - 1
   B0 = 1.0
141 W = BUP(B0, A0, Y0, X0, N, EPS)
IF (X0 .GT. 0.7) GO TO 150
W = W + BPSER(A0, B0, X0, EPS)
W1 = 0.5 + (0.5 - W)
GO TO 220
!
150 IF (A0 .GT. 15.0) GO TO 151
   N = 20
   W = W + BUP(A0, B0, X0, Y0, N, EPS)
   A0 = A0 + N
151 CALL BGRAT(A0, B0, X0, Y0, W, 15.0*EPS, IERR1)
W1 = 0.5 + (0.5 - W)
GO TO 220
!
180 W = BASYM(A0, B0, LAMBDA, 100.0*EPS)
W1 = 0.5 + (0.5 - W)
GO TO 220
!
!               TERMINATION OF THE PROCEDURE
!
200 IF (A .EQ. 0.0) GO TO 350
201 W = 0.0
W1 = 1.0
RETURN
!
210 IF (B .EQ. 0.0) GO TO 360
211 W = 1.0
W1 = 0.0
RETURN
!
220 IF (IND .EQ. 0) RETURN
T = W
W = W1
W1 = T
RETURN
!
!           PROCEDURE FOR A AND B .LT. 1.E-3*EPS
!
230 W = B/(A + B)
W1 = A/(A + B)
RETURN
!
!                       ERROR RETURN
!
300 IERR = 1
RETURN
310 IERR = 2
RETURN
320 IERR = 3
RETURN
330 IERR = 4
RETURN
340 IERR = 5
RETURN
350 IERR = 6
RETURN
360 IERR = 7
RETURN
END SUBROUTINE BRATIO

REAL function FPSER (A, B, X, EPS)
IMPLICIT NONE
INTENT(IN) A, B, EPS, X
REAL A, B, EPS, X
REAL AN, C, S, T, TOL
REAL EXPARG
!-----------------------------------------------------------------------
!
!                 EVALUATION OF I (A,B)
!                                X
!
!          FOR B .LT. MIN(EPS,EPS*A) AND X .LE. 0.5.
!
!-----------------------------------------------------------------------
!
!                  SET  FPSER = X**A
!
FPSER = 1.0
IF (A .LE. 1.E-3*EPS) GO TO 10
FPSER = 0.0
T = A*ALOG(X)
IF (T .LT. EXPARG(1)) RETURN
FPSER = EXP(T)
!
!                NOTE THAT 1/B(A,B) = B
!
10 FPSER = (B/A)*FPSER
TOL = EPS/A
AN = A + 1.0
T = X
S = T/AN
20 AN = AN + 1.0
   T = X*T
   C = T/AN
   S = S + C
   IF (ABS(C) .GT. TOL) GO TO 20
!
FPSER = FPSER*(1.0 + A*S)
RETURN
END FUNCTION FPSER

REAL function APSER (A, B, X, EPS)
IMPLICIT NONE
INTENT(IN) A, B, EPS, X
REAL A, B, EPS, X
REAL AJ, BX, C, G, S, T, TOL
REAL PSI
!-----------------------------------------------------------------------
!     APSER YIELDS THE INCOMPLETE BETA RATIO I(SUB(1-X))(B,A) FOR
!     A .LE. MIN(EPS,EPS*B), B*X .LE. 1, AND X .LE. 0.5. USED WHEN
!     A IS VERY SMALL. USE ONLY IF ABOVE INEQUALITIES ARE SATISFIED.
!-----------------------------------------------------------------------
REAL J
!--------------------
DATA G/.577215664901533/
!--------------------
BX = B*X
T = X - BX
IF (B*EPS .GT. 2.E-2) GO TO 10
   C = ALOG(X) + PSI(B) + G + T
   GO TO 20
10 C = ALOG(BX) + G + T
!
20 TOL = 5.0*EPS*ABS(C)
J = 1.0
S = 0.0
30 J = J + 1.0
   T = T*(X - BX/J)
   AJ = T/J
   S = S + AJ
   IF (ABS(AJ) .GT. TOL) GO TO 30
!
APSER = -A*(C + S)
RETURN
END FUNCTION APSER

REAL function BPSER(A, B, X, EPS)
IMPLICIT NONE
INTENT(IN) A, B, EPS, X
REAL A, B, EPS, X
INTEGER I, M
REAL A0, APB, B0, C, SUM, T, TOL, U, W, Z
REAL ALGDIV, BETALN, GAM1, GAMLN1
!-----------------------------------------------------------------------
!     POWER SERIES EXPANSION FOR EVALUATING IX(A,B) WHEN B .LE. 1
!     OR B*X .LE. 0.7.  EPS IS THE TOLERANCE USED.
!-----------------------------------------------------------------------
REAL N
!
BPSER = 0.0
IF (X .EQ. 0.0) RETURN
!-----------------------------------------------------------------------
!            COMPUTE THE FACTOR X**A/(A*BETA(A,B))
!-----------------------------------------------------------------------
A0 = AMIN1(A,B)
IF (A0 .LT. 1.0) GO TO 10
   Z = A*ALOG(X) - BETALN(A,B)
   BPSER = EXP(Z)/A
   GO TO 70
10 B0 = AMAX1(A,B)
IF (B0 .GE. 8.0) GO TO 60
IF (B0 .GT. 1.0) GO TO 40
!
!            PROCEDURE FOR A0 .LT. 1 AND B0 .LE. 1
!
BPSER = X**A
IF (BPSER .EQ. 0.0) RETURN
!
APB = A + B
IF (APB .GT. 1.0) GO TO 20
   Z = 1.0 + GAM1(APB)
   GO TO 30
20 U = DBLE(A) + DBLE(B) - 1.D0
Z = (1.0 + GAM1(U))/APB
!
30 C = (1.0 + GAM1(A))*(1.0 + GAM1(B))/Z
BPSER = BPSER*C*(B/APB)
GO TO 70
!
!         PROCEDURE FOR A0 .LT. 1 AND 1 .LT. B0 .LT. 8
!
40 U = GAMLN1(A0)
M = B0 - 1.0
IF (M .LT. 1) GO TO 50
C = 1.0
do 41 I = 1,M
   B0 = B0 - 1.0
41 C = C*(B0/(A0 + B0))
U = ALOG(C) + U
!
50 Z = A*ALOG(X) - U
B0 = B0 - 1.0
APB = A0 + B0
IF (APB .GT. 1.0) GO TO 51
   T = 1.0 + GAM1(APB)
   GO TO 52
51 U = DBLE(A0) + DBLE(B0) - 1.D0
T = (1.0 + GAM1(U))/APB
52 BPSER = EXP(Z)*(A0/A)*(1.0 + GAM1(B0))/T
GO TO 70
!
!            PROCEDURE FOR A0 .LT. 1 AND B0 .GE. 8
!
60 U = GAMLN1(A0) + ALGDIV(A0,B0)
Z = A*ALOG(X) - U
BPSER = (A0/A)*EXP(Z)
70 IF (BPSER .EQ. 0.0 .OR. A .LE. 0.1*EPS) RETURN
!-----------------------------------------------------------------------
!                     COMPUTE THE SERIES
!-----------------------------------------------------------------------
SUM = 0.0
N = 0.0
C = 1.0
TOL = EPS/A
100 N = N + 1.0
   C = C*(0.5 + (0.5 - B/N))*X
   W = C/(A + N)
   SUM = SUM + W
   IF (ABS(W) .GT. TOL) GO TO 100
BPSER = BPSER*(1.0 + A*SUM)
RETURN
END FUNCTION BPSER

REAL function BUP(A, B, X, Y, N, EPS)
IMPLICIT NONE
INTENT(IN) A, B, EPS, N, X, Y
INTEGER N
REAL A, B, EPS, X, Y
INTEGER I, K, KP1, MU, NM1
REAL AP1, APB, D, R, T, W
REAL BRCMP1, EXPARG
!-----------------------------------------------------------------------
!     EVALUATION OF IX(A,B) - IX(A+N,B) WHERE N IS A POSITIVE INTEGER.
!     EPS IS THE TOLERANCE USED.
!-----------------------------------------------------------------------
REAL L
!
!          OBTAIN THE SCALING FACTOR EXP(-MU) AND
!             EXP(MU)*(X**A*Y**B/BETA(A,B))/A
!
APB = A + B
AP1 = A + 1.0
MU = 0
D = 1.0
IF (N .EQ. 1 .OR. A .LT. 1.0) GO TO 10
IF (APB .LT. 1.1*AP1) GO TO 10
   MU = ABS(EXPARG(1))
   K = EXPARG(0)
   IF (K .LT. MU) MU = K
   T = MU
   D = EXP(-T)
!
10 BUP = BRCMP1(MU,A,B,X,Y)/A
IF (N .EQ. 1 .OR. BUP .EQ. 0.0) RETURN
NM1 = N - 1
W = D
!
!          LET K BE THE INDEX OF THE MAXIMUM TERM
!
K = 0
IF (B .LE. 1.0) GO TO 40
IF (Y .GT. 1.E-4) GO TO 20
   K = NM1
   GO TO 30
20 R = (B - 1.0)*X/Y - A
IF (R .LT. 1.0) GO TO 40
K = NM1
T = NM1
IF (R .LT. T) K = R
!
!          ADD THE INCREASING TERMS OF THE SERIES
!
30 DO I = 1,K
   L = I - 1
   D = ((APB + L)/(AP1 + L))*X*D
   W = W + D
END DO
IF (K .EQ. NM1) GO TO 50
!
!          ADD THE REMAINING TERMS OF THE SERIES
!
40 KP1 = K + 1
DO I = KP1,NM1
   L = I - 1
   D = ((APB + L)/(AP1 + L))*X*D
   W = W + D
   IF (D .LE. EPS*W) GO TO 50
END DO
!
!               TERMINATE THE PROCEDURE
!
50 BUP = BUP*W
RETURN
END FUNCTION BUP

REAL function BFRAC(A, B, X, Y, LAMBDA, EPS)
IMPLICIT NONE
INTENT(IN) A, B, EPS, LAMBDA, X, Y
REAL A, B, EPS, X, Y
REAL ALPHA, AN, ANP1, BETA, BN, BNP1, C, C0, C1, E, P, R, R0, S, T &
&, W, YP1
REAL BRCOMP
!-----------------------------------------------------------------------
!     CONTINUED FRACTION EXPANSION FOR IX(A,B) WHEN A,B .GT. 1.
!     IT IS ASSUMED THAT  LAMBDA = (A + B)*Y - B.
!-----------------------------------------------------------------------
REAL LAMBDA, N
!--------------------
BFRAC = BRCOMP(A,B,X,Y)
IF (BFRAC .EQ. 0.0) RETURN
!
C = 1.0 + LAMBDA
C0 = B/A
C1 = 1.0 + 1.0/A
YP1 = Y + 1.0
!
N = 0.0
P = 1.0
S = A + 1.0
AN = 0.0
BN = 1.0
ANP1 = 1.0
BNP1 = C/C1
R = C1/C
!
!        CONTINUED FRACTION CALCULATION
!
10 N = N + 1.0
   T = N/A
   W = N*(B - N)*X
   E = A/S
   ALPHA = (P*(P + C0)*E*E)*(W*X)
   E = (1.0 + T)/(C1 + T + T)
   BETA = N + W/S + E*(C + N*YP1)
   P = 1.0 + T
   S = S + 2.0
!
!        UPDATE AN, BN, ANP1, AND BNP1
!
   T = ALPHA*AN + BETA*ANP1
   AN = ANP1
   ANP1 = T
   T = ALPHA*BN + BETA*BNP1
   BN = BNP1
   BNP1 = T
!
   R0 = R
   R = ANP1/BNP1
   IF (ABS(R - R0) .LE. EPS*R) GO TO 20
!
!        RESCALE AN, BN, ANP1, AND BNP1
!
   AN = AN/BNP1
   BN = BN/BNP1
   ANP1 = R
   BNP1 = 1.0
   GO TO 10
!
!                 TERMINATION
!
20 BFRAC = BFRAC*R
RETURN
END FUNCTION BFRAC

REAL function BRCOMP (A, B, X, Y)
IMPLICIT NONE
INTENT(IN) A, B, X, Y
REAL A, B, X, Y
INTEGER I, N
REAL A0, APB, B0, C, CONST, E, H, T, U, V, X0, Y0, Z
REAL ALGDIV, ALNREL, BCORR, BETALN, GAM1, GAMLN1, RLOG1
!-----------------------------------------------------------------------
!               EVALUATION OF X**A*Y**B/BETA(A,B)
!-----------------------------------------------------------------------
REAL LAMBDA, LNX, LNY
!-----------------
!     CONST = 1/SQRT(2*PI)
!-----------------
DATA CONST/.398942280401433/
!
BRCOMP = 0.0
IF (X .EQ. 0.0 .OR. Y .EQ. 0.0) RETURN
A0 = AMIN1(A,B)
IF (A0 .GE. 8.0) GO TO 100
!
IF (X .GT. 0.375) GO TO 10
   LNX = ALOG(X)
   LNY = ALNREL(-X)
   GO TO 20
10 IF (Y .GT. 0.375) GO TO 11
   LNX = ALNREL(-Y)
   LNY = ALOG(Y)
   GO TO 20
11 LNX = ALOG(X)
LNY = ALOG(Y)
!
20 Z = A*LNX + B*LNY
IF (A0 .LT. 1.0) GO TO 30
Z = Z - BETALN(A,B)
BRCOMP = EXP(Z)
RETURN
!-----------------------------------------------------------------------
!              PROCEDURE FOR A .LT. 1 OR B .LT. 1
!-----------------------------------------------------------------------
30 B0 = AMAX1(A,B)
IF (B0 .GE. 8.0) GO TO 80
IF (B0 .GT. 1.0) GO TO 60
!
!                   ALGORITHM FOR B0 .LE. 1
!
BRCOMP = EXP(Z)
IF (BRCOMP .EQ. 0.0) RETURN
!
APB = A + B
IF (APB .GT. 1.0) GO TO 40
   Z = 1.0 + GAM1(APB)
   GO TO 50
40 U = DBLE(A) + DBLE(B) - 1.D0
Z = (1.0 + GAM1(U))/APB
!
50 C = (1.0 + GAM1(A))*(1.0 + GAM1(B))/Z
BRCOMP = BRCOMP*(A0*C)/(1.0 + A0/B0)
RETURN
!
!                ALGORITHM FOR 1 .LT. B0 .LT. 8
!
60 U = GAMLN1(A0)
N = B0 - 1.0
IF (N .LT. 1) GO TO 70
C = 1.0
DO I = 1,N
   B0 = B0 - 1.0
   C = C*(B0/(A0 + B0))
END DO
U = ALOG(C) + U
!
70 Z = Z - U
B0 = B0 - 1.0
APB = A0 + B0
IF (APB .GT. 1.0) GO TO 71
   T = 1.0 + GAM1(APB)
   GO TO 72
71 U = DBLE(A0) + DBLE(B0) - 1.D0
T = (1.0 + GAM1(U))/APB
72 BRCOMP = A0*EXP(Z)*(1.0 + GAM1(B0))/T
RETURN
!
!                   ALGORITHM FOR B0 .GE. 8
!
80 U = GAMLN1(A0) + ALGDIV(A0,B0)
BRCOMP = A0*EXP(Z - U)
RETURN
!-----------------------------------------------------------------------
!              PROCEDURE FOR A .GE. 8 AND B .GE. 8
!-----------------------------------------------------------------------
100 IF (A .GT. B) GO TO 101
   H = A/B
   X0 = H/(1.0 + H)
   Y0 = 1.0/(1.0 + H)
   LAMBDA = A - (A + B)*X
   GO TO 110
101 H = B/A
X0 = 1.0/(1.0 + H)
Y0 = H/(1.0 + H)
LAMBDA = (A + B)*Y - B
!
110 E = -LAMBDA/A
IF (ABS(E) .GT. 0.6) GO TO 111
   U = RLOG1(E)
   GO TO 120
111 U = E - ALOG(X/X0)
!
120 E = LAMBDA/B
IF (ABS(E) .GT. 0.6) GO TO 121
   V = RLOG1(E)
   GO TO 130
121 V = E - ALOG(Y/Y0)
!
130 Z = EXP(-(A*U + B*V))
BRCOMP = CONST*SQRT(B*X0)*Z*EXP(-BCORR(A,B))
RETURN
END FUNCTION BRCOMP

REAL function BRCMP1 (MU, A, B, X, Y)
IMPLICIT NONE
INTENT(IN) A, B, MU, X, Y
INTEGER MU
REAL A, B, X, Y
INTEGER I, N
REAL A0, APB, B0, C, CONST, E, H, T, U, V, X0, Y0, Z
REAL ALGDIV, ALNREL, BCORR, BETALN, ESUM, GAM1, GAMLN1, RLOG1
!-----------------------------------------------------------------------
!          EVALUATION OF  EXP(MU) * (X**A*Y**B/BETA(A,B))
!-----------------------------------------------------------------------
REAL LAMBDA, LNX, LNY
!-----------------
!     CONST = 1/SQRT(2*PI)
!-----------------
DATA CONST/.398942280401433/
!
A0 = AMIN1(A,B)
IF (A0 .GE. 8.0) GO TO 100
!
IF (X .GT. 0.375) GO TO 10
   LNX = ALOG(X)
   LNY = ALNREL(-X)
   GO TO 20
10 IF (Y .GT. 0.375) GO TO 11
   LNX = ALNREL(-Y)
   LNY = ALOG(Y)
   GO TO 20
11 LNX = ALOG(X)
LNY = ALOG(Y)
!
20 Z = A*LNX + B*LNY
IF (A0 .LT. 1.0) GO TO 30
Z = Z - BETALN(A,B)
BRCMP1 = ESUM(MU,Z)
RETURN
!-----------------------------------------------------------------------
!              PROCEDURE FOR A .LT. 1 OR B .LT. 1
!-----------------------------------------------------------------------
30 B0 = AMAX1(A,B)
IF (B0 .GE. 8.0) GO TO 80
IF (B0 .GT. 1.0) GO TO 60
!
!                   ALGORITHM FOR B0 .LE. 1
!
BRCMP1 = ESUM(MU,Z)
IF (BRCMP1 .EQ. 0.0) RETURN
!
APB = A + B
IF (APB .GT. 1.0) GO TO 40
   Z = 1.0 + GAM1(APB)
   GO TO 50
40 U = DBLE(A) + DBLE(B) - 1.D0
Z = (1.0 + GAM1(U))/APB
!
50 C = (1.0 + GAM1(A))*(1.0 + GAM1(B))/Z
BRCMP1 = BRCMP1*(A0*C)/(1.0 + A0/B0)
RETURN
!
!                ALGORITHM FOR 1 .LT. B0 .LT. 8
!
60 U = GAMLN1(A0)
N = B0 - 1.0
IF (N .LT. 1) GO TO 70
C = 1.0
DO I = 1,N
   B0 = B0 - 1.0
   C = C*(B0/(A0 + B0))
END DO
U = ALOG(C) + U
!
70 Z = Z - U
B0 = B0 - 1.0
APB = A0 + B0
IF (APB .GT. 1.0) GO TO 71
   T = 1.0 + GAM1(APB)
   GO TO 72
71 U = DBLE(A0) + DBLE(B0) - 1.D0
T = (1.0 + GAM1(U))/APB
72 BRCMP1 = A0*ESUM(MU,Z)*(1.0 + GAM1(B0))/T
RETURN
!
!                   ALGORITHM FOR B0 .GE. 8
!
80 U = GAMLN1(A0) + ALGDIV(A0,B0)
BRCMP1 = A0*ESUM(MU,Z - U)
RETURN
!-----------------------------------------------------------------------
!              PROCEDURE FOR A .GE. 8 AND B .GE. 8
!-----------------------------------------------------------------------
100 IF (A .GT. B) GO TO 101
   H = A/B
   X0 = H/(1.0 + H)
   Y0 = 1.0/(1.0 + H)
   LAMBDA = A - (A + B)*X
   GO TO 110
101 H = B/A
X0 = 1.0/(1.0 + H)
Y0 = H/(1.0 + H)
LAMBDA = (A + B)*Y - B
!
110 E = -LAMBDA/A
IF (ABS(E) .GT. 0.6) GO TO 111
   U = RLOG1(E)
   GO TO 120
111 U = E - ALOG(X/X0)
!
120 E = LAMBDA/B
IF (ABS(E) .GT. 0.6) GO TO 121
   V = RLOG1(E)
   GO TO 130
121 V = E - ALOG(Y/Y0)
!
130 Z = ESUM(MU,-(A*U + B*V))
BRCMP1 = CONST*SQRT(B*X0)*Z*EXP(-BCORR(A,B))
RETURN
END FUNCTION BRCMP1

SUBROUTINE BGRAT(A, B, X, Y, W, EPS, IERR)
IMPLICIT NONE
INTENT(IN) A, B, EPS, X, Y
INTENT(INOUT) IERR, W
INTEGER IERR
REAL A, B, EPS, W, X, Y
INTEGER I, N, NM1
REAL BM1, BP2N, CN, COEF, DJ, P, Q, R, S, SUM, T, T2, U, V, Z
REAL ALGDIV, ALNREL, GAM1
!-----------------------------------------------------------------------
!     ASYMPTOTIC EXPANSION FOR IX(A,B) WHEN A IS LARGER THAN B.
!     THE RESULT OF THE EXPANSION IS ADDED TO W. IT IS ASSUMED
!     THAT A .GE. 15 AND B .LE. 1.  EPS IS THE TOLERANCE USED.
!     IERR IS A VARIABLE THAT REPORTS THE STATUS OF THE RESULTS.
!-----------------------------------------------------------------------
REAL J, L, LNX, NU, N2
REAL C(30), D(30)
!
BM1 = (B - 0.5) - 0.5
NU = A + 0.5*BM1
IF (Y .GT. 0.375) GO TO 10
   LNX = ALNREL(-Y)
   GO TO 11
10 LNX = ALOG(X)
11 Z = -NU*LNX
IF (B*Z .EQ. 0.0) GO TO 100
!
!                 COMPUTATION OF THE EXPANSION
!                 SET R = EXP(-Z)*Z**B/GAMMA(B)
!
R = B*(1.0 + GAM1(B))*EXP(B*ALOG(Z))
R = R*EXP(A*LNX)*EXP(0.5*BM1*LNX)
U = ALGDIV(B,A) + B*ALOG(NU)
U = R*EXP(-U)
IF (U .EQ. 0.0) GO TO 100
CALL GRAT1(B,Z,R,P,Q,EPS)
!
V = 0.25*(1.0/NU)**2
T2 = 0.25*LNX*LNX
L = W/U
J = Q/R
SUM = J
T = 1.0
CN = 1.0
N2 = 0.0
DO N = 1,30
   BP2N = B + N2
   J = (BP2N*(BP2N + 1.0)*J + (Z + BP2N + 1.0)*T)*V
   N2 = N2 + 2.0
   T = T*T2
   CN = CN/(N2*(N2 + 1.0))
   C(N) = CN
   S = 0.0
   IF (N .EQ. 1) GO TO 21
      NM1 = N - 1
      COEF = B - N
      do 20 I = 1,NM1
         S = S + COEF*C(I)*D(N-I)
20 COEF = COEF + B
21 D(N) = BM1*CN + S/N
   DJ = D(N)*J
   SUM = SUM + DJ
   IF (SUM .LE. 0.0) GO TO 100
   IF (ABS(DJ) .LE. EPS*(SUM + L)) GO TO 30
END DO
!
!                    ADD THE RESULTS TO W
!
30 IERR = 0
W = W + U*SUM
RETURN
!
!               THE EXPANSION CANNOT BE COMPUTED
!
100 IERR = 1
RETURN
END SUBROUTINE BGRAT

SUBROUTINE GRAT1 (A,X,R,P,Q,EPS)
IMPLICIT NONE
INTENT(IN) A, EPS, R, X
INTENT(INOUT) P, Q
REAL A, EPS, P, Q, R, X
REAL A2N, A2NM1, AM0, AN, AN0, B2N, B2NM1, C, CMA, G, H, SUM, T &
&, TOL, W, Z
REAL ERFC1, GAM1, REXP
REAL J, L
!-----------------------------------------------------------------------
!        EVALUATION OF THE INCOMPLETE GAMMA RATIO FUNCTIONS
!                      P(A,X) AND Q(A,X)
!
!     IT IS ASSUMED THAT A .LE. 1.  EPS IS THE TOLERANCE TO BE USED.
!     THE INPUT ARGUMENT R HAS THE VALUE E**(-X)*X**A/GAMMA(A).
!-----------------------------------------------------------------------
IF (A*X .EQ. 0.0) GO TO 130
IF (A .EQ. 0.5) GO TO 120
IF (X .LT. 1.1) GO TO 10
GO TO 50
!
!             TAYLOR SERIES FOR P(A,X)/X**A
!
10 AN = 3.0
C = X
SUM = X/(A + 3.0)
TOL = 0.1*EPS/(A + 1.0)
11 AN = AN + 1.0
   C = -C*(X/AN)
   T = C/(A + AN)
   SUM = SUM + T
   IF (ABS(T) .GT. TOL) GO TO 11
J = A*X*((SUM/6.0 - 0.5/(A + 2.0))*X + 1.0/(A + 1.0))
!
Z = A*ALOG(X)
H = GAM1(A)
G = 1.0 + H
IF (X .LT. 0.25) GO TO 20
   IF (A .LT. X/2.59) GO TO 40
   GO TO 30
20 IF (Z .GT. -.13394) GO TO 40
!
30 W = EXP(Z)
P = W*G*(0.5 + (0.5 - J))
Q = 0.5 + (0.5 - P)
RETURN
!
40 L = REXP(Z)
W = 0.5 + (0.5 + L)
Q = (W*J - L)*G - H
IF (Q .LT. 0.0) GO TO 110
P = 0.5 + (0.5 - Q)
RETURN
!
!              CONTINUED FRACTION EXPANSION
!
50 A2NM1 = 1.0
A2N = 1.0
B2NM1 = X
B2N = X + (1.0 - A)
C = 1.0
51 A2NM1 = X*A2N + C*A2NM1
   B2NM1 = X*B2N + C*B2NM1
   AM0 = A2NM1/B2NM1
   C = C + 1.0
   CMA = C - A
   A2N = A2NM1 + CMA*A2N
   B2N = B2NM1 + CMA*B2N
   AN0 = A2N/B2N
   IF (ABS(AN0 - AM0) .GE. EPS*AN0) GO TO 51
Q = R*AN0
P = 0.5 + (0.5 - Q)
RETURN
!
!                SPECIAL CASES
!
100 P = 0.0
Q = 1.0
RETURN
!
110 P = 1.0
Q = 0.0
RETURN
!
120 IF (X .GE. 0.25) GO TO 121
P = ERF(SQRT(X))
Q = 0.5 + (0.5 - P)
RETURN
121 Q = ERFC1(0,SQRT(X))
P = 0.5 + (0.5 - Q)
RETURN
!
130 IF (X .LE. A) GO TO 100
GO TO 110
END SUBROUTINE GRAT1

REAL function BASYM(A, B, LAMBDA, EPS)
IMPLICIT NONE
INTENT(IN) A, B, EPS, LAMBDA
REAL A, B, EPS
INTEGER I, IM1, IMJ, J, M, MM1, MMJ, N, NP1, NUM
REAL BSUM, DSUM, E0, E1, F, H, H2, HN, R, R0, R1, S, SUM, T, T0 &
&, T1, U, W, W0, Z, Z0, Z2, ZN, ZNM1
REAL BCORR, ERFC1, RLOG1
!-----------------------------------------------------------------------
!     ASYMPTOTIC EXPANSION FOR IX(A,B) FOR LARGE A AND B.
!     LAMBDA = (A + B)*Y - B  AND EPS IS THE TOLERANCE USED.
!     IT IS ASSUMED THAT LAMBDA IS NONNEGATIVE AND THAT
!     A AND B ARE GREATER THAN OR EQUAL TO 15.
!-----------------------------------------------------------------------
REAL J0, J1, LAMBDA
REAL A0(21), B0(21), C(21), D(21)
!------------------------
!     ****** NUM IS THE MAXIMUM VALUE THAT N CAN TAKE IN THE DO LOOP
!            ENDING AT STATEMENT 50. IT IS REQUIRED THAT NUM BE EVEN.
!            THE ARRAYS A0, B0, C, D HAVE DIMENSION NUM + 1.
!
                DATA NUM/20/
!------------------------
!     E0 = 2/SQRT(PI)
!     E1 = 2**(-3/2)
!------------------------
DATA E0/1.12837916709551/, E1/.353553390593274/
!------------------------
BASYM = 0.0
IF (A .GE. B) GO TO 10
   H = A/B
   R0 = 1.0/(1.0 + H)
   R1 = (B - A)/B
   W0 = 1.0/SQRT(A*(1.0 + H))
   GO TO 20
10 H = B/A
R0 = 1.0/(1.0 + H)
R1 = (B - A)/A
W0 = 1.0/SQRT(B*(1.0 + H))
!
20 F = A*RLOG1(-LAMBDA/A) + B*RLOG1(LAMBDA/B)
T = EXP(-F)
IF (T .EQ. 0.0) RETURN
Z0 = SQRT(F)
Z = 0.5*(Z0/E1)
Z2 = F + F
!
A0(1) = (2.0/3.0)*R1
C(1) = - 0.5*A0(1)
D(1) = - C(1)
J0 = (0.5/E0)*ERFC1(1,Z0)
J1 = E1
SUM = J0 + D(1)*W0*J1
!
S = 1.0
H2 = H*H
HN = 1.0
W = W0
ZNM1 = Z
ZN = Z2
DO N = 2, NUM, 2
   HN = H2*HN
   A0(N) = 2.0*R0*(1.0 + H*HN)/(N + 2.0)
   NP1 = N + 1
   S = S + HN
   A0(NP1) = 2.0*R1*S/(N + 3.0)
!
   do 41 I = N, NP1
   R = -0.5*(I + 1.0)
   B0(1) = R*A0(1)
   do 31 M = 2, I
      BSUM = 0.0
      MM1 = M - 1
      do 30 J = 1, MM1
         MMJ = M - J
30 BSUM = BSUM + (J*R - MMJ)*A0(J)*B0(MMJ)
31 B0(M) = R*A0(M) + BSUM/M
   C(I) = B0(I)/(I + 1.0)
!
   DSUM = 0.0
   IM1 = I - 1
   do 40 J = 1, IM1
      IMJ = I - J
40 DSUM = DSUM + D(IMJ)*C(J)
41 D(I) = -(DSUM + C(I))
!
   J0 = E1*ZNM1 + (N - 1.0)*J0
   J1 = E1*ZN + N*J1
   ZNM1 = Z2*ZNM1
   ZN = Z2*ZN
   W = W0*W
   T0 = D(N)*W*J0
   W = W0*W
   T1 = D(NP1)*W*J1
   SUM = SUM + (T0 + T1)
   IF ((ABS(T0) + ABS(T1)) .LE. EPS*SUM) GO TO 60
   END DO
!
60 U = EXP(-BCORR(A,B))
BASYM = E0*T*U*SUM
RETURN
END FUNCTION BASYM

SUBROUTINE ISUBX (A0, B0, X0, P, IERR, EPS)
IMPLICIT NONE
INTENT(IN) A0, B0, EPS, X0
INTENT(OUT) IERR, P
INTEGER IERR
REAL A0, B0, EPS, P, X0
INTEGER IND, L, MAX
REAL A, AFRAC, AM1, AN, B, BFRAC, C, GAMRAT, P0, PIHALF, RPINV &
&, RTY, SUM, T, TEMP, TOL, X, Y
REAL ALGDIV
INTEGER IPMPAR
REAL BLND
REAL ALNREL
REAL I, J, K, LAMBDA, M, N, W(10), Z(10)
!     -------------------
DATA W(1) /6.6671344308688E-2/,  W(2) /1.4945134915058E-1/, &
&W(3) /2.1908636251598E-1/,  W(4) /2.6926671931000E-1/, &
&W(5) /2.9552422471475E-1/,  W(6) /2.9552422471475E-1/, &
&W(7) /2.6926671931000E-1/,  W(8) /2.1908636251598E-1/, &
&W(9) /1.4945134915058E-1/,  W(10)/6.6671344308688E-2/
DATA Z(1) /1.3046735791414E-2/,  Z(2) /6.7468316655507E-2/, &
&Z(3) /1.6029521585049E-1/,  Z(4) /2.8330230293538E-1/, &
&Z(5) /4.2556283050918E-1/,  Z(6) /5.7443716949081E-1/, &
&Z(7) /7.1669769706462E-1/,  Z(8) /8.3970478414951E-1/, &
&Z(9) /9.3253168334449E-1/,  Z(10)/9.8695326420859E-1/
!     -------------------
!     RPINV = 1/SQRT(PI)
!     -------------------
DATA PIHALF /1.5707963267949/
DATA RPINV  /.56418958354776/
!     -------------------
!     ****** MAX IS A MACHINE DEPENDENT CONSTANT. MAX IS THE
!            LARGEST POSITIVE INTEGER THAT MAY BE USED.
!
               MAX = IPMPAR(3)
!
!     -------------------
A = A0
B = B0
X = X0
Y = 0.5 + (0.5 - X)
!
!                        CHECK THE ARGUMENTS
!
P = 0.0
IERR = 1
IF (A .LT. 0.5 .OR. B .LT. 0.5) GO TO 410
IF (X .EQ. 0.0 .OR. X .EQ. 1.0) GO TO 300
IF (X .LT. 0.0) GO TO 400
M = MAX
IF (A .GE. M .OR. B .GT. 70.0 .OR. Y .LT. 0.0) GO TO 411
K = INT(A)
J = INT(B)
AFRAC = A - K
BFRAC = B - J
IF ((AFRAC .NE. 0.0 .AND. AFRAC .NE. 0.5) .OR. &
&(BFRAC .NE. 0.0 .AND. BFRAC .NE. 0.5)) GO TO 420
IF (A .GE. 5000.0 .AND. X .LT. 0.96) RETURN
!
!                      CHECK IF B IS AN INTEGER
!
IND = 0
TOL = 0.5*AMAX1(EPS, 1.E-11)
IF (BFRAC .NE. 0.0) GO TO 100
IF (AFRAC .NE. 0.0) GO TO 20
IF (A .GE. B) GO TO 20
!
!                        INTERCHANGE A AND B
!
10 IND = 1
T = B
B = A
A = T
T = Y
Y = X
X = T
T = J
J = K
K = T
!
!                        COMPUTE EXPANSION 14
!
20 AM1 = A - 1.0
N = 1.0
IF (AM1 .LT. 0.5) GO TO 30
N = J
IF (Y .GE. 2.0*J*X) GO TO 30
T = AM1*Y/X + 1.0
IF (T .LT. J) N = INT(T)
!
30 I = N - 1.0
C = (A*ALOG(X) + I*ALNREL(-X)) - BLND(A,I)
IF (C .LE. -30) GO TO 60
TOL = TOL/J
AN = EXP(C)
IF (AN .LE. TOL) GO TO 60
IF (AN .GE. 1.0 - TOL) GO TO 330
!
C = AN
SUM = 0.0
40 I = I + 1.0
IF (I .GE. J) GO TO 50
C = ((AM1 + I)/I)*Y*C
SUM = SUM + C
IF (C .GT. TOL) GO TO 40
!
50 I = N
C = AN
51 I = I - 1.0
IF (I .EQ. 0.0) GO TO 52
C = I*C/((I + AM1)*Y)
SUM = SUM + C
IF (C .GT. TOL) GO TO 51
52 P = AN + SUM
!
60 IF (P .GE. 1.0) P = 1.0
IF (IND .EQ. 0) RETURN
P = 0.5 + (0.5 - P)
IF (P .LT. 0.0) P = 0.0
RETURN
!
!                SELECTION OF THE APPROPRIATE ALGORITHM
!
100 AM1 = A - 1.0
IF (A .GT. 70.0) GO TO 150
IF (AFRAC .EQ. 0.0) GO TO 10
!
!                COMPUTE P0 = IX(A,1/2) OR P0 = IX(1/2,B)
!                           USING FORMULA 22
!
TEMP = SQRT(X)
RTY  = SQRT(Y)
C = ATAN(TEMP/RTY)/PIHALF
IF (K .EQ. 0.0) GO TO 130
IND = J
M = K + K
TEMP = -TEMP
!
110 I = 0.0
T = 1.0
SUM = 0.0
111 I = I + 2.0
IF (I .EQ. M) GO TO 120
T = X*(I/(I + 1.0))*T
SUM = T + SUM
GO TO 111
!
120 P0 = (SUM + 1.0)*TEMP*RTY/PIHALF + C
IF (IND .NE. 0) GO TO 200
P = P0
RETURN
!
130 IF (J .EQ. 0.0) GO TO 310
M = J + J
X = Y
GO TO 110
!
!                  COMPUTE P0 = IX(A,1/2) FOR A .GT. 70
!                       USING EXPANSION 52 OR 53
!
150 P0 = 0.0
IF (X .LT. 0.7) GO TO 200
T = TOL**(1.0/AM1)
IF (X .LE. T) GO TO 200
!
T = 0.5 + (0.5 - T)
LAMBDA = SQRT(T)
RTY = SQRT(Y)
GAMRAT = RPINV*EXP(-ALGDIV(0.5,A))
IF (T .GE. 4.0*Y) GO TO 170
!
C = LAMBDA - RTY
TEMP = 2.0*RTY
SUM = 0.0
do 160 L = 1,10
   T = C*Z(L)
160 SUM = SUM + W(L)*(X - T*(T + TEMP))**AM1
P0 = C*GAMRAT*SUM + 0.5*TOL
GO TO 200
!
170 SUM = 0.0
do 171 L = 1,10
   T = 1.0 - Y*Z(L)*Z(L)
171 SUM = SUM + W(L)*T**AM1
P0 = 1.0 - RTY*GAMRAT*SUM
!
!                     COMPUTE P USING EXPANSION 21
!
200 IF (J .EQ. 0.0) GO TO 251
N = J
IF (Y .GE. 2.0*J*X) GO TO 210
T = AM1*Y/X + 0.5
IF (T .GE. 2.0) GO TO 201
   N = 1.0
   GO TO 210
201 IF (T .LT. J) N = INT(T)
!
210 T = N - 0.5
C = (A*ALOG(X) + T*ALNREL(-X)) - BLND(A,T)
IF (C .LE. -30.0) GO TO 251
C = EXP(C)
IF (C .LE. TOL/J) GO TO 251
IF (P0 + C .GE. 1.0 - TOL) GO TO 320
!
TOL = TOL/J
LAMBDA = C
SUM = 0.0
220 T = T + 1.0
IF (T .GT. J) GO TO 240
LAMBDA = (AM1 + T)*Y*LAMBDA/T
SUM = SUM + LAMBDA
IF (LAMBDA .GT. TOL) GO TO 220
!
240 LAMBDA = C
T = A - 0.5
I = N
241 I = I - 1.0
IF (I .LE. 0.0) GO TO 250
LAMBDA = ((I + 0.5)/(I + T))*LAMBDA/Y
SUM = LAMBDA + SUM
IF (LAMBDA .GT. TOL) GO TO 241
!
250 P = C + SUM
251 P = P + P0
IF (P .GE. 1.0) P = 1.0
RETURN
!
!                           SPECIAL CASES
!
300 P = X
RETURN
!
310 P = C
RETURN
!
320 P = 1.0
RETURN
!
330 P = 1 - IND
RETURN
!
!                           ERROR RETURN
!
400 IERR = 2
RETURN
!
410 IF (A .LE. 0.0 .OR. B .LE. 0.0) GO TO 400
411 IERR = 3
RETURN
!
420 IERR = 4
RETURN
END SUBROUTINE ISUBX

REAL function BLND(A,B)
IMPLICIT NONE
INTENT(IN) A, B
REAL A, B
REAL ALGDIV
REAL LOGAM
!
IF (A .GT. 20.0) GO TO 10
   BLND = (LOGAM(A) - LOGAM(A + B)) + LOGAM(B + 1.0)
   RETURN
10 BLND = ALGDIV(B,A) + LOGAM(B + 1.0)
RETURN
END FUNCTION BLND

REAL function LOGAM (X)
IMPLICIT NONE
INTENT(IN) X
REAL X
INTEGER N
REAL D, T, Z
REAL W(200)
!     ------------------------------------------------------------------
!     COMPUTATION OF LN(GAMMA(X)) FOR X = N/2  WHERE N IS AN INTEGER
!     ------------------------------------------------------------------
!     D = 0.5*(LN(2*PI) - 1)
!     ---------------------
DATA D/.41893853320467/
!     ---------------------
DATA W(1)  /.57236494292470E+00/, W(2)  /0.0/, &
&W(3) /-.12078223763525E+00/, W(4)  /0.0/, &
&W(5)  /.28468287047292E+00/, W(6)  /.69314718055995E+00/, &
&W(7)  /.12009736023471E+01/, W(8)  /.17917594692281E+01/, &
&W(9)  /.24537365708424E+01/, W(10) /.31780538303479E+01/, &
&W(11) /.39578139676187E+01/, W(12) /.47874917427820E+01/, &
&W(13) /.56625620598571E+01/, W(14) /.65792512120101E+01/, &
&W(15) /.75343642367587E+01/, W(16) /.85251613610654E+01/, &
&W(17) /.95492672573010E+01/, W(18) /.10604602902745E+02/, &
&W(19) /.11689333420797E+02/, W(20) /.12801827480081E+02/
DATA W(21) /.13940625219404E+02/, W(22) /.15104412573076E+02/, &
&W(23) /.16292000476567E+02/, W(24) /.17502307845874E+02/, &
&W(25) /.18734347511936E+02/, W(26) /.19987214495662E+02/, &
&W(27) /.21260076156245E+02/, W(28) /.22552163853123E+02/, &
&W(29) /.23862765841689E+02/, W(30) /.25191221182739E+02/, &
&W(31) /.26536914491116E+02/, W(32) /.27899271383841E+02/, &
&W(33) /.29277754515041E+02/, W(34) /.30671860106081E+02/, &
&W(35) /.32081114895947E+02/, W(36) /.33505073450137E+02/, &
&W(37) /.34943315776877E+02/, W(38) /.36395445208033E+02/, &
&W(39) /.37861086508961E+02/, W(40) /.39339884187199E+02/
DATA W(41) /.40831500974531E+02/, W(42) /.42335616460753E+02/, &
&W(43) /.43851925860675E+02/, W(44) /.45380138898477E+02/, &
&W(45) /.46919978795809E+02/, W(46) /.48471181351835E+02/, &
&W(47) /.50033494105019E+02/, W(48) /.51606675567764E+02/, &
&W(49) /.53190494526169E+02/, W(50) /.54784729398112E+02/, &
&W(51) /.56389167643720E+02/, W(52) /.58003605222981E+02/, &
&W(53) /.59627846095884E+02/, W(54) /.61261701761002E+02/, &
&W(55) /.62904990828877E+02/, W(56) /.64557538627006E+02/, &
&W(57) /.66219176833549E+02/, W(58) /.67889743137182E+02/, &
&W(59) /.69569080920824E+02/, W(60) /.71257038967168E+02/
DATA W(61) /.72953471184169E+02/, W(62) /.74658236348830E+02/, &
&W(63) /.76371197867783E+02/, W(64) /.78092223553315E+02/, &
&W(65) /.79821185413614E+02/, W(66) /.81557959456115E+02/, &
&W(67) /.83302425502950E+02/, W(68) /.85054467017582E+02/, &
&W(69) /.86813970941781E+02/, W(70) /.88580827542198E+02/, &
&W(71) /.90354930265818E+02/, W(72) /.92136175603687E+02/, &
&W(73) /.93924462962300E+02/, W(74) /.95719694542143E+02/, &
&W(75) /.97521775222888E+02/, W(76) /.99330612454787E+02/, &
&W(77) /.10114611615586E+03/, W(78) /.10296819861451E+03/, &
&W(79) /.10479677439716E+03/, W(80) /.10663176026064E+03/
DATA W(81) /.10847307506907E+03/, W(82) /.11032063971476E+03/, &
&W(83) /.11217437704318E+03/, W(84) /.11403421178146E+03/, &
