&W(147)/.24112190696703E+03/, W(148)/.24326884900298E+03/, &
&W(149)/.24541919237325E+03/, W(150)/.24757291409619E+03/, &
&W(151)/.24972999149863E+03/, W(152)/.25189040220972E+03/, &
&W(153)/.25405412415489E+03/, W(154)/.25622113555001E+03/, &
&W(155)/.25839141489572E+03/, W(156)/.26056494097186E+03/, &
&W(157)/.26274169283208E+03/, W(158)/.26492164979855E+03/, &
&W(159)/.26710479145687E+03/, W(160)/.26929109765102E+03/
DATA W(161)/.27148054847853E+03/, W(162)/.27367312428569E+03/, &
&W(163)/.27586880566295E+03/, W(164)/.27806757344037E+03/, &
&W(165)/.28026940868320E+03/, W(166)/.28247429268763E+03/, &
&W(167)/.28468220697654E+03/, W(168)/.28689313329543E+03/, &
&W(169)/.28910705360840E+03/, W(170)/.29132395009427E+03/, &
&W(171)/.29354380514276E+03/, W(172)/.29576660135076E+03/, &
&W(173)/.29799232151870E+03/, W(174)/.30022094864701E+03/, &
&W(175)/.30245246593264E+03/, W(176)/.30468685676567E+03/, &
&W(177)/.30692410472600E+03/, W(178)/.30916419358015E+03/, &
&W(179)/.31140710727802E+03/, W(180)/.31365282994988E+03/
DATA W(181)/.31590134590330E+03/, W(182)/.31815263962021E+03/, &
&W(183)/.32040669575401E+03/, W(184)/.32266349912673E+03/, &
&W(185)/.32492303472629E+03/, W(186)/.32718528770378E+03/, &
&W(187)/.32945024337081E+03/, W(188)/.33171788719693E+03/, &
&W(189)/.33398820480710E+03/, W(190)/.33626118197920E+03/, &
&W(191)/.33853680464160E+03/, W(192)/.34081505887080E+03/, &
&W(193)/.34309593088909E+03/, W(194)/.34537940706227E+03/, &
&W(195)/.34766547389743E+03/, W(196)/.34995411804077E+03/, &
&W(197)/.35224532627544E+03/, W(198)/.35453908551944E+03/, &
&W(199)/.35683538282361E+03/, W(200)/.35913420536958E+03/
!     ------------------------------------------------------------------
IF (X .GT. 100.0) GO TO 10
   N = 2.0*X + 0.1
   LOGAM = W(N)
   RETURN
10 T = (1.0/X)**2
Z = (((-0.75*T + 1.0)*T - 3.5)*T + 105.0)/(X*1260.0)
LOGAM = (D + Z) + (X - 0.5)*(ALOG(X) - 1.0)
RETURN
END FUNCTION LOGAM

SUBROUTINE CBSSLJ (Z, CNU, W)
IMPLICIT NONE
INTENT(IN) CNU
INTENT(INOUT) W
INTEGER I, K, M, N
REAL A, CN1, CN2, E, FN, PI, PN, QM, QN, QNP1, R, R2, RN2, SN, T1 &
&, T2, U, V, X, Y
REAL CPABS
!-----------------------------------------------------------------------
!
!         EVALUATION OF THE COMPLEX BESSEL FUNCTION J   (Z)
!                                                    CNU
!-----------------------------------------------------------------------
!
!     WRITTEN BY
!         ANDREW H. VAN TUYL AND ALFRED H. MORRIS, JR.
!         NAVAL SURFACE WARFARE CENTER
!         OCTOBER, 1991
!
!     A MODIFICATION OF THE PROCEDURE DEVELOPED BY ALLEN V. HERSHEY
!     (NAVAL SURFACE WARFARE CENTER) IN 1978 FOR HANDLING THE DEBYE
!     APPROXIMATION IS EMPLOYED.
!
!-----------------------------------------------------------------------
COMPLEX Z, CNU, W
COMPLEX C, NU, S, SM1, SM2, T, TSC, W0, W1, ZN, ZZ
COMPLEX CDIV, CGAM0
!-----------------------
DATA PI /3.14159265358979/
!-----------------------
X = REAL(Z)
Y = AIMAG(Z)
R = CPABS(X,Y)
CN1 = REAL(CNU)
CN2 = AIMAG(CNU)
RN2 = CN1*CN1 + CN2*CN2
PN = AINT(CN1)
FN = CN1 - PN
!
!          CALCULATION WHEN ORDER IS AN INTEGER
!
SN = 1.0
IF (FN .NE. 0.0 .OR. CN2 .NE. 0.0) GO TO 10
N = PN
PN = ABS(PN)
CN1 = PN
IF (N .LT. 0 .AND. N .NE. (N/2)*2) SN = -1.0
!
!          SELECTION OF METHOD
!
10 IF (R .LE. 17.5) GO TO 20
IF (R .GT. 17.5 + 0.5*RN2) GO TO 40
GO TO 50
!
!          USE MACLAURIN EXPANSION AND RECURSION
!
20 IF (CN1 .GE. 0.0) GO TO 30
QN = -1.25*(R + 0.5*ABS(CN2) - ABS(Y - 0.5*CN2))
IF (CN1 .GE. QN) GO TO 30
QN = 1.25*(R - AMAX1(1.2*R,ABS(Y - CN2)))
IF (CN1 .GE. QN) GO TO 30
QN = AMIN1(PN, -AINT(1.25*(R - ABS(CN2))))
GO TO 130
!
30 R2 = R*R
QM = 0.0625*R2*R2 - CN2*CN2
QN = AMAX1(PN, AINT(SQRT(0.5*(QM + ABS(QM)))))
GO TO 130
!
!          USE ASYMPTOTIC EXPANSION
!
40 CALL CBJA(Z, CNU, W)
RETURN
!
!          CALCULATION FOR 17.5 .LT. ABS(Z) .LE. 17.5 + 0.5*ABS(CNU)**2
!
50 N = 0
IF (ABS(CN2) .GE. 0.8*ABS(Y)) GO TO 60
QM = -1.25*(R + 0.5*ABS(CN2) - ABS(Y - 0.5*CN2))
IF (CN1 .GE. QM) GO TO 60
QM = 1.25*(R - AMAX1(1.2*R,ABS(Y - CN2)))
IF (CN1 .LT. QM) N = 1
!
60 QN = PN
A = 4.E-3*R*R
ZZ = Z
IF (X .LT. 0.0) ZZ = -Z
!
!          CALCULATION OF ZONE OF EXCLUSION OF DEBYE APPROXIMATION
!
70 NU = CMPLX(QN + FN, CN2)
   ZN = NU/Z
   T2 = AIMAG(ZN)*AIMAG(ZN)
   U = 1.0 - REAL(ZN)
   T1 = U*U + T2
   U = 1.0 + REAL(ZN)
   T2 = U*U + T2
   U = T1*T2
   V = A*U/(T1*T1 + T2*T2)
   IF (U*V*V .GT. 1.0) GO TO 80
!
!          THE ARGUMENT LIES INSIDE THE ZONE OF EXCLUSION
!
   QN = QN + 1.0
   IF (N .EQ. 0) GO TO 70
!
!          USE MACLAURIN EXPANSION WITH FORWARD RECURRENCE
!
QN = AMIN1(PN, -AINT(1.25*(R - ABS(CN2))))
GO TO 130
!
!          USE BACKWARD RECURRENCE STARTING FROM THE
!          ASYMPTOTIC EXPANSION
!
80 QNP1 = QN + 1.0
IF (ABS(QN) .GE. ABS(PN)) GO TO 100
IF (R .LT. 17.5 + 0.5*(QNP1*QNP1 + CN2*CN2)) GO TO 100
!
NU = CMPLX(QN + FN, CN2)
CALL CBJA (ZZ, NU, SM1)
NU = CMPLX(QNP1 + FN, CN2)
CALL CBJA (ZZ, NU, SM2)
GO TO 110
!
!          USE BACKWARD RECURRENCE STARTING FROM THE
!          DEBYE APPROXIMATION
!
100 NU = CMPLX(QN + FN, CN2)
CALL CBDB (ZZ, NU, FN, SM1)
IF (QN .EQ. PN) GO TO 120
NU = CMPLX(QNP1 + FN, CN2)
CALL CBDB (ZZ, NU, FN, SM2)
!
110 NU = CMPLX(QN + FN, CN2)
   TSC = 2.0*NU*SM1/ZZ - SM2
   SM2 = SM1
   SM1 = TSC
   QN = QN - 1.0
   IF (QN .NE. PN) GO TO 110
!
120 W = SM1
IF (SN .LT. 0.0) W = -W
IF (X .GE. 0.0) RETURN
!
NU = PI*CMPLX(-CN2, CN1)
IF (Y .LT. 0.0) NU = -NU
W = CEXP(NU)*W
RETURN
!
!          USE MACLAURIN EXPANSION WITH FORWARD OR BACKWARD RECURRENCE.
!
130 M = QN - PN
IF (IABS(M) .GT. 1) GO TO 140
   NU = CMPLX(CN1, CN2)
   CALL CBJM (Z, NU, W)
   GO TO 180
140 NU = CMPLX(QN + FN, CN2)
CALL CBJM (Z, NU, W1)
W0 = 0.25*Z*Z
IF (M .GT. 0) GO TO 160
!
!          FORWARD RECURRENCE
!
M = IABS(M)
NU = NU + 1.0
CALL CBJM (Z, NU, W)
DO I = 2,M
   C = NU*(NU + 1.0)
   T = (C/W0)*(W - W1)
   W1 = W
   W = T
   NU = NU + 1.0
END DO
GO TO 180
!
!          BACKWARD RECURRENCE
!
160 NU = NU - 1.0
CALL CBJM (Z, NU, W)
DO I = 2,M
   C = NU*(NU + 1.0)
   T = (W0/C)*W1
   W1 = W
   W = W - T
   NU = NU - 1.0
END DO
!
!          FINAL ASSEMBLY
!
180 IF (FN .NE. 0.0 .OR. CN2 .NE. 0.0) GO TO 190
   K = PN
   IF (K .EQ. 0.0) RETURN
   E = SN/GAMMA(PN + 1.0)
   W = E*W*(0.5*Z)**K
   RETURN
!
190 S = CNU*CLOG(0.5*Z)
W = CEXP(S)*W
IF (RN2 .GT. 0.81) GO TO 200
   W = W*CGAM0(CNU)
   RETURN
200 CALL CGAMMA(0, CNU, T)
W = CDIV(W, CNU*T)
RETURN
END SUBROUTINE CBSSLJ

SUBROUTINE CBJM (Z, CNU, W)
IMPLICIT NONE
INTENT(IN) CNU
INTENT(INOUT) W
INTEGER I, IMIN, K, KM1, KM2
REAL A, A0, EPS, RNU
REAL ANORM
REAL SPMPAR
!-----------------------------------------------------------------------
!
!       COMPUTATION OF  (Z/2)**(-CNU) * GAMMA(CNU + 1) * J(CNU,Z)
!
!                           -----------------
!
!     THE MACLAURIN EXPANSION IS USED. IT IS ASSUMED THAT CNU IS NOT
!     A NEGATIVE INTEGER.
!
!-----------------------------------------------------------------------
COMPLEX CNU, NU, NUP1, P, S, SN, T, TI, W, Z
REAL INU, M
COMPLEX CDIV
!--------------------------
ANORM(Z) = AMAX1(ABS(REAL(Z)),ABS(AIMAG(Z)))
!--------------------------
!
!     ****** EPS IS A MACHINE DEPENDENT CONSTANT. EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1.0 + EPS .GT. 1.0 .
!
                EPS = SPMPAR(1)
!
!--------------------------
S = -0.25*(Z*Z)
NU = CNU
RNU = REAL(NU)
INU = AIMAG(NU)
A = 0.5 + (0.5 + RNU)
NUP1 = CMPLX(A, INU)
!
IF (A .LE. 0.0) GO TO 10
M = 1.0
T = S/NUP1
W = 1.0 + T
GO TO 70
!
!     ADD 1.0 AND THE FIRST K-1 TERMS
!
10 K = INT(-A) + 2
KM1 = K - 1
W = (1.0, 0.0)
T = W
DO I = 1,KM1
   M = I
   T = T*(S/(M*(NU + M)))
   W = W + T
   IF (ANORM(T) .LE. EPS*ANORM(W)) GO TO 30
END DO
GO TO 70
!
!     CHECK IF THE (K-1)-ST AND K-TH TERMS CAN BE IGNORED.
!     IF SO THEN THE SUMMATION IS COMPLETE.
!
30 IF (I .EQ. KM1) GO TO 70
IMIN = I + 1
IF (IMIN .GE. K - 5) GO TO 50
TI = T
!
M = KM1
T = S/(NU + M)
A0 = ANORM(T)/M
T = T * (S/(NU + (M + 1.0)))
A = ANORM(T)/(M*(M + 1.0))
A = AMAX1(A, A0)
!
T = (1.0, 0.0)
KM2 = K - 2
DO I = IMIN,KM2
   M = I
   T = T*(S/(M*(NU + M)))
   IF (A*ANORM(T) .LT. 0.5) RETURN
END DO
T = T*TI
IMIN = KM2
!
!     ADD THE (K-1)-ST TERM
!
50 A = 1.0
P = (1.0, 0.0)
SN = P
DO I = IMIN,KM1
   M = I
   A = A*M
   P = P*(NU + M)
   SN = S*SN
END DO
T = T*(CDIV(SN,P)/A)
W = W + T
!
!     ADD THE REMAINING TERMS
!
70 M = M + 1.0
T = T*(S/(M*(NU + M)))
W = W + T
IF (ANORM(T) .GT. EPS*ANORM(W)) GO TO 70
!
RETURN
END SUBROUTINE CBJM

SUBROUTINE CBDB (CZ, CNU, FN, W)
IMPLICIT NONE
INTENT(IN) CNU, CZ, FN
INTENT(INOUT) W
REAL FN
INTEGER IND, K, L, M
REAL ALPHA, AM, AQ, AR, BND, C, PHI, PI, PI2, SGN, THETA, U, V, X &
&, Y
!-----------------------------------------------------------------------
!
!         CALCULATION OF J   (CZ) BY THE DEBYE APPROXIMATION
!                         CNU
!                         ------------------
!
!     IT IS ASSUMED THAT REAL(CZ) .GE. 0 AND THAT REAL(CNU) = FN + K
!     WHERE K IS AN INTEGER.
