COMPLEX CZ, CNU, W
REAL A(136), IS, INU, IZN
COMPLEX C1, C2, ETA, J, NU, P, P1, Q, R, S, S1, S2, SM, T, Z, ZN
!----------------------
!     C = 1/SQRT(2)
!     BND = PI/3
!----------------------
DATA J   /(0.0, 1.0)/
