&9.16426474122779E-06, 1.56477785428873E-05, 2.08223629482467E-05/
DATA GAMA(1),   GAMA(2),   GAMA(3),   GAMA(4),   GAMA(5), &
&GAMA(6),   GAMA(7),   GAMA(8),   GAMA(9),   GAMA(10), &
&GAMA(11),  GAMA(12),  GAMA(13),  GAMA(14),  GAMA(15), &
&GAMA(16),  GAMA(17),  GAMA(18),  GAMA(19),  GAMA(20), &
&GAMA(21),  GAMA(22),  GAMA(23),  GAMA(24),  GAMA(25), &
&GAMA(26)        / 6.29960524947437E-01, 2.51984209978975E-01, &
&1.54790300415656E-01, 1.10713062416159E-01, 8.57309395527395E-02, &
&6.97161316958684E-02, 5.86085671893714E-02, 5.04698873536311E-02, &
&4.42600580689155E-02, 3.93720661543510E-02, 3.54283195924455E-02, &
&3.21818857502098E-02, 2.94646240791158E-02, 2.71581677112934E-02, &
&2.51768272973862E-02, 2.34570755306079E-02, 2.19508390134907E-02, &
&2.06210828235646E-02, 1.94388240897881E-02, 1.83810633800683E-02, &
&1.74293213231963E-02, 1.65685837786612E-02, 1.57865285987918E-02, &
&1.50729501494096E-02, 1.44193250839955E-02, 1.38184805735342E-02/
!     ------------------------------------------------------------------
FN = FNU
IFLW = 0
do 170 JN = 1,IN
  XX = X/FN
  WK(1) = 1.0E0 - XX*XX
  ABW2 = ABS(WK(1))
  WK(2) = SQRT(ABW2)
  WK(7) = FN**CON2
  IF (ABW2.GT.0.27750E0) GO TO 80
!
!     ASYMPTOTIC EXPANSION
!     CASES NEAR X=FN, ABS(1.-(X/FN)**2).LE.0.2775
!     COEFFICIENTS OF ASYMPTOTIC EXPANSION BY SERIES
!
!     ZETA AND TRUNCATION FOR A(ZETA) AND B(ZETA) SERIES
!
!     KMAX IS TRUNCATION INDEX FOR A(ZETA) AND B(ZETA) SERIES=MAX(2,SA)
!
  SA = 0.0E0
  IF (ABW2.EQ.0.0E0) GO TO 10
  SA = TOLS/ALOG(ABW2)
10 SB = SA
  do 20 I = 1,5
    AKM = AMAX1(SA,2.0E0)
    KMAX(I) = INT(AKM)
    SA = SA + SB
20 CONTINUE
  KB = KMAX(5)
  KLAST = KB - 1
  SA = GAMA(KB)
  do 30 K = 1,KLAST
    KB = KB - 1
    SA = SA*WK(1) + GAMA(KB)
30 CONTINUE
  Z = WK(1)*SA
  AZ = ABS(Z)
  RTZ = SQRT(AZ)
  WK(3) = CON1*AZ*RTZ
  WK(4) = WK(3)*FN
  WK(5) = RTZ*WK(7)
  WK(6) = -WK(5)*WK(5)
  IF(Z.LE.0.0E0) GO TO 35
  IF(WK(4).GT.ELIM) GO TO 75
  WK(6) = -WK(6)
35 CONTINUE
  PHI = SQRT(SQRT(SA+SA+SA+SA))
!
!     B(ZETA) FOR S=0
!
  KB = KMAX(5)
  KLAST = KB - 1
  SB = BETA(KB,1)
  do 40 K = 1,KLAST
    KB = KB - 1
    SB = SB*WK(1) + BETA(KB,1)
40 CONTINUE
  KSP1 = 1
  FN2 = FN*FN
  RFN2 = 1.0E0/FN2
  RDEN = 1.0E0
  ASUM = 1.0E0
  RELB = TOL*ABS(SB)
  BSUM = SB
  do 60 KS = 1,4
    KSP1 = KSP1 + 1
    RDEN = RDEN*RFN2
!
!     A(ZETA) AND B(ZETA) FOR S=1,2,3,4
!
    KSTEMP = 5 - KS
    KB = KMAX(KSTEMP)
    KLAST = KB - 1
    SA = ALFA(KB,KS)
    SB = BETA(KB,KSP1)
    do 50 K = 1,KLAST
      KB = KB - 1
      SA = SA*WK(1) + ALFA(KB,KS)
      SB = SB*WK(1) + BETA(KB,KSP1)
50 CONTINUE
    TA = SA*RDEN
    TB = SB*RDEN
    ASUM = ASUM + TA
    BSUM = BSUM + TB
    IF (ABS(TA).LE.TOL .AND. ABS(TB).LE.RELB) GO TO 70
60 CONTINUE
70 CONTINUE
  BSUM = BSUM/(FN*WK(7))
  GO TO 160
!
75 CONTINUE
  IFLW = 1
  RETURN
!
80 CONTINUE
  UPOL(1) = 1.0E0
  TAU = 1.0E0/WK(2)
  T2 = 1.0E0/WK(1)
  IF (WK(1).GE.0.0E0) GO TO 90
!
!     CASES FOR (X/FN).GT.SQRT(1.2775)
!
  WK(3) = ABS(WK(2)-ATAN(WK(2)))
  WK(4) = WK(3)*FN
  RCZ = -CON1/WK(4)
  Z32 = 1.5E0*WK(3)
  RTZ = Z32**CON2
  WK(5) = RTZ*WK(7)
  WK(6) = -WK(5)*WK(5)
  GO TO 100
90 CONTINUE
!
!     CASES FOR (X/FN).LT.SQRT(0.7225)
!
  WK(3) = ABS(ALOG((1.0E0+WK(2))/XX)-WK(2))
  WK(4) = WK(3)*FN
  RCZ = CON1/WK(4)
  IF(WK(4).GT.ELIM) GO TO 75
  Z32 = 1.5E0*WK(3)
  RTZ = Z32**CON2
  WK(7) = FN**CON2
  WK(5) = RTZ*WK(7)
  WK(6) = WK(5)*WK(5)
100 CONTINUE
  PHI = SQRT((RTZ+RTZ)*TAU)
  TB = 1.0E0
  ASUM = 1.0E0
  TFN = TAU/FN
  UPOL(2) = (C(1)*T2+C(2))*TFN
  CRZ32 = CON548*RCZ
  BSUM = UPOL(2) + CRZ32
  RELB = TOL*ABS(BSUM)
  AP = TFN
  KS = 0
  KP1 = 2
  RZDEN = RCZ
  L = 2
  DO LR=2,8,2
!
!     COMPUTE TWO U POLYNOMIALS FOR NEXT A(ZETA) AND B(ZETA)
!
    LRP1 = LR + 1
    DO K=LR,LRP1
      KS = KS + 1
      KP1 = KP1 + 1
      L = L + 1
      S1 = C(L)
      DO J=2,KP1
        L = L + 1
        S1 = S1*T2 + C(L)
      END DO
      AP = AP*TFN
      UPOL(KP1) = AP*S1
      CR(KS) = BR(KS)*RZDEN
      RZDEN = RZDEN*RCZ
      DR(KS) = AR(KS)*RZDEN
    END DO
    SUMA = UPOL(LRP1)
    SUMB = UPOL(LR+2) + UPOL(LRP1)*CRZ32
    JU = LRP1
    DO JR=1,LR
      JU = JU - 1
      SUMA = SUMA + CR(JR)*UPOL(JU)
      SUMB = SUMB + DR(JR)*UPOL(JU)
    END DO
    TB = -TB
    IF (WK(1).GT.0.0E0) TB = ABS(TB)
    ASUM = ASUM + SUMA*TB
    BSUM = BSUM + SUMB*TB
    IF (ABS(SUMA).LE.TOL .AND. ABS(SUMB).LE.RELB) GO TO 150
  END DO
150 TB = WK(5)
  IF (WK(1).GT.0.0E0) TB = -TB
  BSUM = BSUM/TB
!
160 CONTINUE
  CALL FUNJY(WK(6), WK(5), WK(4), FI, DFI)
  Y(JN) = FLGJY*PHI*(FI*ASUM+DFI*BSUM)/WK(7)
  FN = FN - FLGJY
170 CONTINUE
RETURN
END SUBROUTINE ASJY

SUBROUTINE JAIRY(X,RX,C,AI,DAI)
IMPLICIT NONE
INTENT(IN) C, RX, X
INTENT(INOUT) AI, DAI
REAL AI, C, DAI, RX, X
INTEGER I, J, M1, M1D, M2, M2D, M3, M3D, M4, M4D, N1, N1D, N2, N2D &
&, N3, N3D, N4, N4D
REAL A, AJN, AJP, AK1, AK2, AK3, B, CCV, CON1, CON2, CON3, CON4 &
&, CON5, CV, DA, DAJN, DAJP, DAK1, DAK2, DAK3, DB, E1, E2, EC, F1 &
&, F2, FPI12, RTRX, SCV, T, TEMP1, TEMP2, TT
!
!                  JAIRY COMPUTES THE AIRY FUNCTION AI(X)
!                   AND ITS DERIVATIVE DAI(X) FOR JBESS
!
!                                   INPUT
!
!         X - ARGUMENT, COMPUTED BY JBESS, X UNRESTRICTED
!        RX - RX=SQRT(ABS(X)), COMPUTED BY JBESS
!         C - C=2.*(ABS(X)**1.5)/3., COMPUTED BY JBESS
!
!                                  OUTPUT
!
!        AI - VALUE OF FUNCTION AI(X)
!       DAI - VALUE OF THE DERIVATIVE DAI(X)
!
!                                WRITTEN BY
!
!                                D. E. AMOS
!                               S. L. DANIEL
!                               M. K. WESTON
