!
DATA AJP(1) / 7.78952966437581E-02/, &
&AJP(2) /-1.84356363456801E-01/, AJP(3) / 3.01412605216174E-02/, &
&AJP(4) / 3.05342724277608E-02/, AJP(5) /-4.95424702513079E-03/, &
&AJP(6) /-1.72749552563952E-03/, AJP(7) / 2.43137637839190E-04/, &
