SUBROUTINE CBSSLI (Z, CNU, W)
IMPLICIT NONE
INTENT(IN) CNU, Z
INTENT(INOUT) W
REAL PIHALF, T, X, Y
REAL SIN1
REAL COS1
REAL EXPARG
!------------------------------------------------------------
!     CALCULATION OF THE MODIFIED BESSEL FUNCTION OF THE
!     FIRST KIND FOR COMPLEX ORDER CNU AND COMPLEX ARGUMENT
!     Z.  IT IS ASSUMED THAT -PI .LT. ARG Z .LE. PI.
!------------------------------------------------------------
COMPLEX Z, CNU, W, NU, Z0
!
DATA PIHALF /1.5707963267949/
!
X = REAL(Z)
Y = AIMAG(Z)
IF (Y .LT. 0.0) GO TO 10
   Z0 = CMPLX(Y, -X)
   NU = CNU
   GO TO 20
10 Z0 = CMPLX(-Y, X)
NU = -CNU
!
20 T = -PIHALF*AIMAG(NU)
IF (T .GT. EXPARG(1)) GO TO 30
   W = (0.0, 0.0)
   RETURN
!
30 CALL CBSSLJ (Z0, CNU, W)
W = EXP(T)*W
T = 0.5*REAL(NU)
W = W*CMPLX(COS1(T),SIN1(T))
RETURN
END SUBROUTINE CBSSLI

